CSS=Path('jordan/jordan-pwa.css')
INDEX=Path('jordan/index.html')
SW=Path('jordan/sw.js')

s=JS.read_text(encoding='utf-8')
if 'const BOOK_FUNCTION_WORDS=' in s and 'function saveBookToLibrary' in s and 'function speakTracked' in s:
    raise SystemExit(0)

# Add stronger book-word filtering and persistent book library helpers after grade skip helper.
anchor="function shouldSkipForGrade(word,grade){const g=String(grade||'');if(db.words.some(w=>String(w.grade)===g&&sameWord(w.word_en,word)))return true;const n=Number(g);if(n>=4&&db.words.some(w=>['1','2','3'].includes(String(w.grade))&&sameWord(w.word_en,word)))return true;return false}\n"
extra=r'''const BOOK_FUNCTION_WORDS=new Set(('a an the this that these those i me my mine myself we us our ours ourselves you your yours yourself yourselves he him his himself she her hers herself it its itself they them their theirs themselves who whom whose which what whoever whatever am is are was were be been being have has had having do does did doing can could may might must shall should will would and or but nor so yet for as if then than because although though while when where whether since until unless about above across after against along among around at before behind below beneath beside besides between beyond by despite down during except from in inside into like near of off on onto opposite outside over past through throughout to toward towards under underneath up upon via with within without not no yes very too also only just even ever never here there now once again each every either neither both all any some many much few little more most less least other another such own same one two first second next last unit lesson page pages chapter section part example question answer').split(' '));
function shouldTranslateBookWord(raw,text,index){const w=String(raw||'').trim(),l=w.toLowerCase();if(!validWord(w,false)||BOOK_FUNCTION_WORDS.has(l)||PROPER.has(l.replace(/[-']/g,'')))return false;if(l.length<3||/^([a-z])\1+$/.test(l)||/^['-]/.test(l)||/['-]$/.test(l))return false;if(/^[A-Z]{2,}$/.test(w))return false;const before=String(text||'').slice(Math.max(0,Number(index||0)-4),Number(index||0));const sentenceStart=Number(index||0)===0||/[.!?]\s*$/.test(before)||/\n\s*$/.test(before);if(!sentenceStart&&/^[A-Z][a-z]{2,}$/.test(w))return false;return true}
const BOOK_LIBRARY_INDEX='booklib:index:v1';
function bookFingerprint(file){return `${String(file?.name||'book')}:${Number(file?.size||0)}:${Number(file?.lastModified||0)}`}
async function loadBookLibrary(){const x=await enrichCacheGet(BOOK_LIBRARY_INDEX);return Array.isArray(x)?x:[]}
async function saveBookLibraryIndex(list){await enrichCacheSet(BOOK_LIBRARY_INDEX,list.slice(0,30))}
async function saveBookToLibrary(file,name){if(!file)return null;const id=bookFingerprint(file),clean=String(name||file.name||'كتاب').trim()||'كتاب';await enrichCacheSet('booklib:file:'+id,file);let list=await loadBookLibrary();const old=list.find(x=>x.id===id);const rec={id,name:clean,fileName:file.name||'',size:Number(file.size||0),lastModified:Number(file.lastModified||0),updatedAt:Date.now(),lastMode:old?.lastMode||''};list=[rec,...list.filter(x=>x.id!==id)];await saveBookLibraryIndex(list);try{await navigator.storage?.persist?.()}catch(_){}return rec}
async function getLibraryBookFile(id){return await enrichCacheGet('booklib:file:'+id)}
async function rememberBookMode(file,mode){if(!file)return;const id=bookFingerprint(file),list=await loadBookLibrary(),rec=list.find(x=>x.id===id);if(rec){rec.lastMode=mode;rec.updatedAt=Date.now();await saveBookLibraryIndex([rec,...list.filter(x=>x.id!==id)])}}
async function removeBookFromLibrary(id){try{const d=await openEnrichDb();await new Promise(resolve=>{const tx=d.transaction('kv','readwrite');tx.objectStore('kv').delete('booklib:file:'+id);tx.oncomplete=resolve;tx.onerror=resolve});d.close()}catch(_){}const list=(await loadBookLibrary()).filter(x=>x.id!==id);await saveBookLibraryIndex(list)}
function speechChunks(text){const clean=String(text||'').replace(/\s+/g,' ').trim();if(!clean)return [];const a=clean.split(/(?<=[.!?])\s+/).map(x=>x.trim()).filter(Boolean);return a.length?a:[clean]}
function renderTrackedText(text,id){return speechChunks(text).map((x,i)=>`<span class="bt-speech-chunk" data-track="${esc(id)}" data-chunk="${i}">${esc(x)}</span>`).join(' ')}
function clearSpeechTracking(){ROOT.querySelectorAll('.bt-speech-chunk.bt-speaking').forEach(x=>x.classList.remove('bt-speaking'))}
function speakTracked(text,id){const chunks=speechChunks(text);if(!chunks.length)return;try{speechSynthesis.cancel()}catch(_){}clearSpeechTracking();let i=0;const next=()=>{if(i>=chunks.length){clearSpeechTracking();return}const el=ROOT.querySelector(`.bt-speech-chunk[data-track="${CSS.escape(String(id))}"][data-chunk="${i}"]`);clearSpeechTracking();if(el){el.classList.add('bt-speaking');el.scrollIntoView?.({block:'nearest',behavior:'smooth'})}const u=new SpeechSynthesisUtterance(chunks[i]);u.lang='en-US';u.rate=.86;u.onend=()=>{i++;next()};u.onerror=()=>{i++;next()};speechSynthesis.speak(u)};next()}
'''
if anchor not in s:
    raise SystemExit('grade helper anchor missing')
s=s.replace(anchor,anchor+extra,1)

# Replace book UI and translation runner block, preserving render().
start=s.find('function bookTranslate(){')
end=s.find('\nfunction render(){',start)
if start<0 or end<0:
    raise SystemExit('book translation block markers missing')
replacement=r'''async function renderBookLibrary(){const box=ROOT.querySelector('#btLibrary');if(!box)return;const list=await loadBookLibrary();if(!list.length){box.innerHTML='<div class="j-note">لا توجد كتب محفوظة بعد. اختر PDF ثم اضغط «حفظ الكتاب».</div>';return}box.innerHTML=list.map(x=>`<div class="bt-book-row"><div><strong>${esc(x.name)}</strong><div class="j-meta">${esc(x.fileName)} • ${Math.max(1,Math.round(Number(x.size||0)/1024/1024))} MB${x.lastMode?` • آخر وضع: ${x.lastMode==='words'?'كلمات':x.lastMode==='sentences'?'جمل':'فقرات'}`:''}</div></div><div class="j-toolbar"><button class="j-btn secondary bt-open-book" data-id="${esc(x.id)}">فتح</button><button class="j-btn light bt-delete-book" data-id="${esc(x.id)}">حذف</button></div></div>`).join('');box.querySelectorAll('.bt-open-book').forEach(b=>b.onclick=async()=>{const rec=list.find(x=>x.id===b.dataset.id),file=await getLibraryBookFile(b.dataset.id);if(!file){alert('ملف الكتاب لم يعد متاحًا في تخزين الجهاز. أعد اختيار PDF وحفظه.');return}window.__btLibraryFile=file;window.__btLibraryRecord=rec;const n=ROOT.querySelector('#btname');if(n)n.value=rec.name;const ch=ROOT.querySelector('#btchoice');if(ch)ch.textContent=`تم فتح الكتاب المحفوظ: ${rec.name}. اختر نوع الترجمة ثم ابدأ/أكمل.`;window.scrollTo({top:0,behavior:'smooth'})});box.querySelectorAll('.bt-delete-book').forEach(b=>b.onclick=async()=>{if(!confirm('حذف الكتاب من مكتبة هذا الجهاز؟'))return;await removeBookFromLibrary(b.dataset.id);if(window.__btLibraryRecord?.id===b.dataset.id){window.__btLibraryFile=null;window.__btLibraryRecord=null}renderBookLibrary()})}
function bookTranslate(){shell(`<div class="j-top"><div><h1 class="j-title">ترجمة كتاب</h1><p class="j-sub">بدون صف أو منهاج • حفظ تلقائي + مكتبة كتب</p></div></div><div class="j-panel"><div class="j-grid"><article class="j-card bt-mode" data-mode="words"><div class="ico">🔤</div><h3>الكلمات ومعانيها</h3><p>كلمات مفيدة فقط؛ يستبعد الضمائر والأدوات والأسماء الواضحة والكلمات الوظيفية البسيطة.</p></article><article class="j-card bt-mode" data-mode="sentences"><div class="ico">💬</div><h3>الجمل ومعانيها</h3><p>يعرض الجملة الإنجليزية وتحتها ترجمتها العربية مع النطق.</p></article><article class="j-card bt-mode" data-mode="paragraphs"><div class="ico">📄</div><h3>الفقرات ومعانيها</h3><p>ترجمة سياقية، ومع النطق يتم تظليل الجملة الجاري نطقها.</p></article></div><div class="j-row" style="margin-top:16px"><input id="btname" class="j-input" placeholder="اسم الكتاب"><input id="btf" type="file" accept="application/pdf" class="j-input"></div><div class="j-toolbar"><button id="btsave" class="j-btn green">💾 حفظ الكتاب</button><button id="btrun" class="j-btn" disabled>ابدأ / أكمل الترجمة</button></div><div id="btchoice" class="j-note">اختر نوع الترجمة. الحفظ التلقائي يحفظ التقدم، وزر «حفظ الكتاب» يحتفظ بالكتاب نفسه في مكتبة الجهاز للعودة إليه لاحقًا.</div><details class="bt-library-wrap" open><summary><strong>📚 كتبي</strong></summary><div id="btLibrary" style="margin-top:10px"></div></details><div id="btp" style="margin-top:12px"></div><div id="btr" class="j-results" style="margin-top:14px"></div></div>`);let mode='';window.__btLibraryFile=null;window.__btLibraryRecord=null;const fi=ROOT.querySelector('#btf'),name=ROOT.querySelector('#btname');fi.onchange=()=>{const f=fi.files?.[0];if(f&&!name.value.trim())name.value=String(f.name||'').replace(/\.pdf$/i,'')};ROOT.querySelectorAll('.bt-mode').forEach(c=>c.onclick=()=>{mode=c.dataset.mode;ROOT.querySelectorAll('.bt-mode').forEach(x=>x.style.outline='');c.style.outline='3px solid var(--j-primary,#0ea5e9)';ROOT.querySelector('#btchoice').textContent=mode==='words'?'النظام: الكلمات المفيدة ومعانيها (مع تصفية الكلمات الوظيفية والأسماء)':mode==='sentences'?'النظام: الجمل ومعانيها':'النظام: الفقرات ومعانيها + مؤشر النطق';ROOT.querySelector('#btrun').disabled=false});ROOT.querySelector('#btsave').onclick=async()=>{const f=fi.files?.[0]||window.__btLibraryFile;if(!f){alert('اختر ملف PDF أولًا');return}const rec=await saveBookToLibrary(f,name.value);window.__btLibraryFile=f;window.__btLibraryRecord=rec;name.value=rec.name;ROOT.querySelector('#btchoice').textContent=`✓ تم حفظ «${rec.name}» في مكتبة هذا الجهاز.`;await renderBookLibrary()};ROOT.querySelector('#btrun').onclick=()=>translateBookRun(mode);renderBookLibrary()}

function renderBookTranslationResults(list,mode,pageIndex=0){const r=ROOT.querySelector('#btr');if(!r)return;const per=60,totalPages=Math.max(1,Math.ceil(list.length/per)),pageNo=Math.max(0,Math.min(pageIndex,totalPages-1)),slice=list.slice(pageNo*per,(pageNo+1)*per),pending=list.filter(x=>mode==='words'?!x.meaning:!x.translation).length;const pager=`<div class="bt-pager"><button class="j-btn secondary bt-prev" ${pageNo===0?'disabled':''}>السابق</button><span class="bt-page-info">${pageNo+1} / ${totalPages}</span><button class="j-btn secondary bt-next" ${pageNo===totalPages-1?'disabled':''}>التالي</button></div>`;const body=mode==='words'?slice.map(x=>`<div class="j-word bt-result-card"><button class="j-btn light j-speak" data-speak="${esc(x.word)}">🔊</button><div class="bt-text-col"><div class="j-word-en">${esc(x.word)}</div><div class="j-word-ar">${esc(x.meaning||'بانتظار الترجمة')}</div><div class="j-meta">ص ${x.page}</div></div><span></span></div>`).join(''):slice.map((x,i)=>{const tid=`bt-${pageNo}-${i}-${x.page}`;return `<div class="j-word bt-result-card"><button class="j-btn light bt-track-speak" data-track-id="${esc(tid)}" data-text="${esc(x.text)}">🔊</button><div class="bt-text-col"><div class="j-example bt-english-block" id="${esc(tid)}">${mode==='paragraphs'?renderTrackedText(x.text,tid):esc(x.text)}</div><div class="j-word-ar bt-arabic-block">${esc(x.translation||'بانتظار الترجمة')}</div><div class="j-meta">ص ${x.page} • ${mode==='paragraphs'?'فقرة':'جملة'}</div></div><span></span></div>`}).join('');r.innerHTML=(pending?`<div class="j-note">متبقي للترجمة: ${pending}. النتائج محفوظة ويمكن إكمالها لاحقًا.</div>`:'')+pager+body+pager;r.querySelectorAll('.bt-prev').forEach(b=>b.onclick=()=>renderBookTranslationResults(list,mode,pageNo-1));r.querySelectorAll('.bt-next').forEach(b=>b.onclick=()=>renderBookTranslationResults(list,mode,pageNo+1));r.querySelectorAll('.bt-track-speak').forEach(b=>b.onclick=()=>mode==='paragraphs'?speakTracked(b.dataset.text||'',b.dataset.trackId):speak(b.dataset.text||''));bindSpeak()}

async function translateBookRun(mode){const f=ROOT.querySelector('#btf')?.files?.[0]||window.__btLibraryFile,p=ROOT.querySelector('#btp'),r=ROOT.querySelector('#btr');if(!f){alert('اختر ملف PDF أو افتح كتابًا من «كتبي» أولًا');return}if(!['words','sentences','paragraphs'].includes(mode)){alert('اختر نوع الترجمة أولًا');return}const bookName=ROOT.querySelector('#btname')?.value?.trim()||window.__btLibraryRecord?.name||String(f.name||'كتاب').replace(/\.pdf$/i,'');await rememberBookMode(f,mode);r.innerHTML='';let saved=await loadWorkSession(f,mode);const words=new Map(),items=[],seen=new Set();let pages=0,startPage=1;if(saved){pages=Number(saved.pages||0);startPage=Math.max(1,pages+1);for(const x of Array.isArray(saved.items)?saved.items:[]){if(mode==='words')words.set(x.word,x);else{items.push(x);seen.add(String(x.text||'').toLowerCase())}}p.innerHTML=`<div class="j-note">${esc(bookName)} • تم العثور على تقدم سابق حتى الصفحة ${pages}. سيتم الاستكمال وإعادة محاولة غير المترجم.</div>`}
try{await extractPdf(f,async(text,pi,total)=>{if(pi<startPage)return;pages=pi;if(mode==='words'){for(const m of text.matchAll(/[A-Za-z][A-Za-z'-]*/g)){const raw=m[0];if(!shouldTranslateBookWord(raw,text,m.index))continue;const key=raw.toLowerCase();if(!words.has(key))words.set(key,{word:key,meaning:'',page:pi})}}else{const source=mode==='paragraphs'?paragraphList(text):sentenceList(text);for(const block of source){const key=block.toLowerCase();if(seen.has(key))continue;seen.add(key);items.push({text:block,translation:'',page:pi})}}const snapshot=mode==='words'?[...words.values()]:items;await saveWorkSession(f,mode,{bookName,pages:pi,totalPages:total,phase:'reading',items:snapshot});p.innerHTML=`<div class="j-progress"><div style="width:${Math.round(pi/total*40)}%"></div></div><p>${esc(bookName)} • قراءة الصفحة ${pi} من ${total} • تم الحفظ تلقائيًا</p>`});const list=mode==='words'?[...words.values()]:items;if(!list.length){p.innerHTML='<div class="j-note">لم يتم العثور على محتوى مناسب بعد تطبيق التصفية.</div>';return}renderBookTranslationResults(list,mode,0);const pending=list.filter(x=>mode==='words'?!x.meaning:!x.translation);const doneBase=list.length-pending.length;if(!pending.length){await saveWorkSession(f,mode,{bookName,pages,phase:'complete',items:list,complete:true});p.innerHTML=`<div class="j-stats"><div class="j-stat">${esc(bookName)}</div><div class="j-stat">${pages} صفحة</div><div class="j-stat">✓ الترجمة مكتملة</div></div>`;return}await mapBookTranslations(pending,async item=>{if(mode==='words'){const x=await enrichVocabulary(item.word);if(x.meaning)item.meaning=x.meaning;return !!item.meaning}else{const tr=await translateEnAr(item.text);if(tr)item.translation=tr;return !!item.translation}},async(done,total,failed)=>{await saveWorkSession(f,mode,{bookName,pages,phase:'translating',items:list});const finished=doneBase+done;p.innerHTML=`<div class="j-progress"><div style="width:${40+Math.round(finished/Math.max(1,list.length)*60)}%"></div></div><p>${esc(bookName)} • الترجمة ${finished} من ${list.length} • حفظ تلقائي • فشل مؤقت ${failed}</p>`;if(done%24===0)renderBookTranslationResults(list,mode,0)});const remaining=list.filter(x=>mode==='words'?!x.meaning:!x.translation).length;await saveWorkSession(f,mode,{bookName,pages,phase:remaining?'partial':'complete',items:list,complete:remaining===0});p.innerHTML=`<div class="j-stats"><div class="j-stat">${esc(bookName)}</div><div class="j-stat">${pages} صفحة</div><div class="j-stat">✓ محفوظ تلقائيًا</div>${remaining?`<div class="j-stat">${remaining} بانتظار إعادة المحاولة</div>`:'<div class="j-stat">الترجمة مكتملة</div>'}</div>${remaining?'<button id="btRetryPending" class="j-btn bt-retry">إعادة محاولة غير المترجم</button>':''}`;renderBookTranslationResults(list,mode,0);const retry=ROOT.querySelector('#btRetryPending');if(retry)retry.onclick=()=>translateBookRun(mode)}catch(e){console.error(e);const list=mode==='words'?[...words.values()]:items;await saveWorkSession(f,mode,{bookName,pages,phase:'interrupted',items:list,error:String(e?.message||e)});renderBookTranslationResults(list,mode,0);p.innerHTML=`<div class="j-note">توقف العمل مؤقتًا، لكن تم حفظ ما تم إنجازه في «${esc(bookName)}» حتى الصفحة ${pages}. يمكنك فتح الكتاب من «كتبي» والمتابعة لاحقًا.</div>`}}
'''
s=s[:start]+replacement+s[end:]
JS.write_text(s,encoding='utf-8')

css=CSS.read_text(encoding='utf-8')
addon='''.bt-result-card{min-width:0}.bt-text-col{min-width:0;max-width:100%;overflow:hidden}.bt-english-block{direction:ltr;text-align:left;unicode-bidi:plaintext;overflow-wrap:anywhere;word-break:normal;white-space:normal;max-width:100%}.bt-arabic-block{direction:rtl;text-align:right;overflow-wrap:anywhere;white-space:normal}.bt-speech-chunk{border-radius:6px;padding:1px 2px;transition:background .15s,box-shadow .15s}.bt-speech-chunk.bt-speaking{background:#fef08a;box-shadow:0 0 0 2px #fde047;color:#713f12}.bt-library-wrap{margin-top:16px;border:1px solid #dbeafe;border-radius:18px;padding:12px;background:#f8fbff}.bt-library-wrap summary{cursor:pointer}.bt-book-row{display:flex;align-items:center;justify-content:space-between;gap:12px;border-top:1px solid #e2e8f0;padding:10px 2px}.bt-book-row:first-child{border-top:0}.bt-book-row .j-toolbar{margin:0;flex-wrap:nowrap}@media(max-width:600px){.bt-book-row{align-items:flex-start;flex-direction:column}.bt-book-row .j-toolbar{width:100%}.bt-book-row .j-btn{flex:1}.j-word.bt-result-card{grid-template-columns:auto minmax(0,1fr);}.j-word.bt-result-card>span:last-child{display:none}}
'''
